"use client";
import { useState } from "react";
import "./image-compare.css";

/** Before and after, split by a handle. Drag anywhere, or use the arrow keys: it is a real range input. */
export function ImageCompare({
  before,
  after,
  beforeAlt,
  afterAlt,
  beforeLabel = "Before",
  afterLabel = "After",
  initial = 50,
  className = "",
}: {
  before: string;
  after: string;
  beforeAlt: string;
  afterAlt: string;
  beforeLabel?: string;
  afterLabel?: string;
  initial?: number;
  className?: string;
}) {
  const [split, setSplit] = useState(initial);
  return (
    <div className={`forme-compare ${className}`} style={{ ["--forme-compare" as string]: `${split}%` }}>
      <img src={after} alt={afterAlt} draggable={false} />
      <img src={before} alt={beforeAlt} draggable={false} className="forme-compare-before" />
      <span className="forme-compare-tag" data-side="before" aria-hidden="true">
        {beforeLabel}
      </span>
      <span className="forme-compare-tag" data-side="after" aria-hidden="true">
        {afterLabel}
      </span>
      <span className="forme-compare-handle" aria-hidden="true">
        <span />
      </span>
      <input
        type="range"
        min={0}
        max={100}
        step={0.5}
        value={split}
        aria-label={`Show more of ${beforeLabel.toLowerCase()} or ${afterLabel.toLowerCase()}`}
        aria-valuetext={`${Math.round(split)}% ${beforeLabel.toLowerCase()}`}
        onChange={(e) => setSplit(Number(e.target.value))}
      />
    </div>
  );
}

.forme-compare {
  --forme-compare: 50%;
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  aspect-ratio: 16 / 10;
  background: #000;
  user-select: none;
}
.forme-compare img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}
.forme-compare-before {
  clip-path: inset(0 calc(100% - var(--forme-compare)) 0 0);
}
.forme-compare-handle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--forme-compare);
  width: 2px;
  background: #fff;
  box-shadow: 0 0 12px #0008;
  transform: translateX(-50%);
  pointer-events: none;
}
.forme-compare-handle span {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #ffffffeb;
  box-shadow: 0 4px 16px #0006;
  transform: translate(-50%, -50%);
}
.forme-compare-handle span::before,
.forme-compare-handle span::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 6px;
  height: 6px;
  border: solid #111;
  border-width: 0 0 1.6px 1.6px;
}
.forme-compare-handle span::before {
  left: 9px;
  transform: translateY(-50%) rotate(45deg);
}
.forme-compare-handle span::after {
  right: 9px;
  transform: translateY(-50%) rotate(-135deg);
}
.forme-compare-tag {
  position: absolute;
  top: 12px;
  padding: 4px 9px;
  border-radius: 999px;
  background: #0009;
  backdrop-filter: blur(8px);
  color: #fff;
  font-size: 12px;
  font-weight: 500;
}
.forme-compare-tag[data-side="before"] {
  left: 12px;
}
.forme-compare-tag[data-side="after"] {
  right: 12px;
}
/* The real control: invisible, full size, so drag works anywhere and keys work on focus. */
.forme-compare input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: ew-resize;
}
.forme-compare:has(input:focus-visible) .forme-compare-handle span {
  outline: 2px solid #fff;
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-compare-handle {
    transition: none;
  }
}
